    REAL, INTENT(INOUT) :: ARR(1:NELM) ! Array to be summed in-place (first element is the sum)

    INTEGER :: I                          ! Loop index
    REAL :: SUM                             ! Temporary variable for computing the sum

    SUM = 0.0
    DO I = 1, NELM
